import { AlertTriangle, ArrowLeft, CheckCircle2, ChevronDown, Clipboard, Clock3, Download, Edit3, ExternalLink, FileImage, FileText, History, Link2, Lock, PackageCheck, Power, RefreshCw, RotateCcw, Save, Search, Send, Share2, ShoppingCart, SlidersHorizontal, Trophy, Users, X } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { api, apiArquivo, date, ErroApi, money } from '../api'
import { usarAutenticacao } from '../autenticacao'
import { EstadoVazio, AvisoErro, Carregando, EtiquetaStatus } from '../components/ComponentesUI'
import type { ComparacaoCotacao, ComparacaoProduto, Cotacao, EstrategiaPedidoMinimo, HistoricoPlano, OpcoesPedidoMinimo, PedidoCompra, PreviaManualPedidoMinimo, RespostaCotacao, ResultadoRestauracaoPlano, VersaoPlano } from '../types'
import { LinkInterno, usarParametros } from '../roteamento'

type Aba='products'|'responses'|'comparison'|'purchase'
type EdicaoPlano={quotationItemId:number;desiredQuantity:number;selectedResponseId:number|null;championQuantity:number|null;stockOverrideNote:string;manualSelection:boolean}
type FormatoPedido='pdf'|'image'
const tituloAba:Record<Aba,string>={products:'Produtos',responses:'Respostas',comparison:'Inteligência de compra',purchase:'Compra sugerida'}
const prazoLocalMais24Horas=(expiraEm:string|null)=>{const agora=new Date(),atual=expiraEm?new Date(expiraEm):agora,base=atual>agora?atual:agora;base.setHours(base.getHours()+24);const pad=(valor:number)=>String(valor).padStart(2,'0');return `${base.getFullYear()}-${pad(base.getMonth()+1)}-${pad(base.getDate())}T${pad(base.getHours())}:${pad(base.getMinutes())}`}

export default function PaginaDetalheCotacao(){
  const finalizando=useRef(false)
  const{id}=usarParametros();const{user}=usarAutenticacao();const[cotacao,setCotacao]=useState<Cotacao|null>(null);const[respostas,setRespostas]=useState<RespostaCotacao[]>([]);const[comparacao,setComparacao]=useState<ComparacaoCotacao|null>(null);const[pedidos,setPedidos]=useState<PedidoCompra[]>([])
  const[aba,setAba]=useState<Aba>('products');const[carregando,setCarregando]=useState(true);const[ocupado,setOcupado]=useState(false);const[erro,setErro]=useState('');const[mensagem,setMensagem]=useState('');const[copiado,setCopiado]=useState('');const[expandidas,setExpandidas]=useState<Set<string>>(new Set());const[produtoTroca,setProdutoTroca]=useState<ComparacaoProduto|null>(null);const[produtoPlano,setProdutoPlano]=useState<number|null>(null);const[edicoes,setEdicoes]=useState<EdicaoPlano[]|null>(null);const[versaoBaseEdicao,setVersaoBaseEdicao]=useState(0);const[errosPlano,setErrosPlano]=useState<Record<string,string>>({});const[prorrogando,setProrrogando]=useState(false);const[novoPrazo,setNovoPrazo]=useState('');const[linkProrrogado,setLinkProrrogado]=useState(false);const[opcoesMinimo,setOpcoesMinimo]=useState<OpcoesPedidoMinimo|null>(null);const[ajusteManual,setAjusteManual]=useState<OpcoesPedidoMinimo|null>(null);const[historico,setHistorico]=useState<HistoricoPlano>({currentVersionId:0,canUndo:false,versions:[]});const[historicoAberto,setHistoricoAberto]=useState(false)
  useEffect(()=>{document.title=`${cotacao?`${cotacao.name} — ${tituloAba[aba]}`:'Cotação'} | CotaPreço`},[cotacao,aba])
  const carregar=useCallback(async()=>{if(!id)return;setCarregando(true);setErro('');try{const[q,r,c,o,h]=await Promise.all([api<Cotacao>(`/quotations/${id}`),api<RespostaCotacao[]>(`/quotations/${id}/responses`),api<ComparacaoCotacao>(`/quotations/${id}/comparison`),api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setCotacao(q);setRespostas(r);setComparacao(c);setPedidos(o);setHistorico(h)}catch(e){setErro(e instanceof ErroApi?e.message:'Falha ao carregar a cotação.')}finally{setCarregando(false)}},[id]);useEffect(()=>{void carregar()},[carregar])
  const atualizarCompra=async()=>{if(!id)return;const[c,o,h]=await Promise.all([api<ComparacaoCotacao>(`/quotations/${id}/comparison`),api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setComparacao(c);setPedidos(o);setHistorico(h)}
  const acao=async(tipo:'open'|'close')=>{setOcupado(true);try{await api(`/quotations/${id}/${tipo}`,{method:'POST'});await carregar()}catch(e){setErro(mensagemErro(e,'Operação não concluída.'))}finally{setOcupado(false)}}
  const atualizarItem=async(itemId:number,quantity:number,active:boolean)=>{if(!active&&!window.confirm('Desativar este produto? Ele será removido do comparativo, da compra sugerida e dos próximos pedidos.'))return;setOcupado(true);setErro('');try{await api(`/quotations/${id}/items/${itemId}`,{method:'PUT',body:JSON.stringify({quantity,active})});await carregar();setMensagem(active?'Produto atualizado.':'Produto desativado e removido dos cálculos da cotação.')}catch(e){setErro(mensagemErro(e,'Não foi possível atualizar o produto.'))}finally{setOcupado(false)}}
  const atualizarRespostaAtiva=async(resposta:RespostaCotacao,active:boolean)=>{if(!active&&!window.confirm(`Desativar a resposta de ${resposta.supplierName}? Ela deixará de influenciar a compra sugerida.`))return;setOcupado(true);setErro('');try{await api(`/quotations/${id}/responses/${resposta.id}/active`,{method:'PUT',body:JSON.stringify({active})});await carregar();setMensagem(active?'Resposta reativada e incluída novamente nos cálculos.':'Resposta desativada e removida da compra sugerida.')}catch(e){setErro(mensagemErro(e,'Não foi possível atualizar a resposta.'))}finally{setOcupado(false)}}
  const copiar=async(valor:string,tipo:string)=>{await navigator.clipboard.writeText(valor);setCopiado(tipo);setTimeout(()=>setCopiado(''),1800)}
  const escolherCampeao=async(itemId:number,responseId:number)=>{setOcupado(true);setErro('');try{await api(`/quotations/${id}/purchase-selections/${itemId}`,{method:'PUT',body:JSON.stringify({responseId})});await atualizarCompra();setProdutoTroca(null)}catch(e){setErro(mensagemErro(e,'Não foi possível trocar o campeão.'))}finally{setOcupado(false)}}
  const voltarAutomatico=async(itemId:number)=>{setOcupado(true);setErro('');try{await api(`/quotations/${id}/purchase-selections/${itemId}`,{method:'DELETE'});await atualizarCompra();setProdutoTroca(null)}catch(e){setErro(mensagemErro(e,'Não foi possível restaurar o cálculo automático.'))}finally{setOcupado(false)}}
  const edicoesAtuais=()=>comparacao?.products.map(p=>({quotationItemId:p.quotationItemId,desiredQuantity:p.desiredQuantity??p.requestedQuantity,selectedResponseId:p.selectedResponseId??null,championQuantity:p.championQuantity??null,stockOverrideNote:p.stockOverrideNote??'',manualSelection:!!p.manualSelection}))??[]
  const abrirPlano=()=>{if(!comparacao)return;setErrosPlano({});setProdutoPlano(null);setVersaoBaseEdicao(historico.currentVersionId);setEdicoes(edicoesAtuais())}
  const abrirProdutoPlano=(produto:ComparacaoProduto)=>{setErrosPlano({});setProdutoPlano(produto.quotationItemId);setVersaoBaseEdicao(historico.currentVersionId);setEdicoes(edicoesAtuais())}
  const salvarPlano=async()=>{if(!edicoes)return;setOcupado(true);setErro('');setErrosPlano({});try{const atualizada=await api<ComparacaoCotacao>(`/quotations/${id}/purchase-plan`,{method:'PUT',body:JSON.stringify({items:edicoes,baseVersionId:versaoBaseEdicao})});setComparacao(atualizada);const[o,h]=await Promise.all([api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setPedidos(o);setHistorico(h);setEdicoes(null);setProdutoPlano(null);setMensagem('Quantidades finais atualizadas. Você pode desfazer ou consultar o histórico.')}catch(e){if(e instanceof ErroApi)setErrosPlano(e.fields);setErro(mensagemErro(e,'Não foi possível atualizar as quantidades.'))}finally{setOcupado(false)}}
  const gerarPedido=async(responseId:number)=>{const grupo=comparacao?.suggestedPurchase.find(item=>item.responseId===responseId);const abaixo=grupo?.minimumOrderStatus==='ABAIXO_DO_MINIMO';if(abaixo&&!window.confirm(`A distribuidora informou mínimo de ${money(grupo.minimumOrderValue!)}. Este pedido está em ${money(grupo.total)} e pode ser rejeitado. Deseja gerar mesmo assim?`))return;setOcupado(true);setErro('');try{await api(`/quotations/${id}/orders/${responseId}`,{method:'PUT',body:JSON.stringify({observation:null,confirmBelowMinimum:abaixo})});await atualizarCompra();setMensagem('Pedido gerado com sucesso em PDF e imagem.')}catch(e){setErro(mensagemErro(e,'Não foi possível gerar o pedido.'))}finally{setOcupado(false)}}
  const obterArquivo=async(pedido:PedidoCompra,formato:FormatoPedido)=>{const extensao=formato==='pdf'?'pdf':'png';const blob=await apiArquivo(`/quotations/${id}/orders/${pedido.id}/${formato}`);return new File([blob],`${pedido.number}.${extensao}`,{type:formato==='pdf'?'application/pdf':'image/png'})}
  const confirmarRiscoPedido=(pedido:PedidoCompra,acao:string)=>!pedido.belowMinimum||window.confirm(`Este pedido está abaixo do mínimo de ${money(pedido.minimumOrderValue!)} e pode ser rejeitado. Deseja ${acao} mesmo assim?`)
  const baixar=async(pedido:PedidoCompra,formato:FormatoPedido)=>{if(!confirmarRiscoPedido(pedido,'baixar o arquivo'))return;setOcupado(true);setErro('');try{const arquivo=await obterArquivo(pedido,formato);const url=URL.createObjectURL(arquivo);const a=document.createElement('a');a.href=url;a.download=arquivo.name;a.click();URL.revokeObjectURL(url)}catch(e){setErro(mensagemErro(e,`Não foi possível baixar ${formato==='pdf'?'o PDF':'a imagem'}.`))}finally{setOcupado(false)}}
  const compartilhar=async(pedido:PedidoCompra,formato:FormatoPedido)=>{if(!confirmarRiscoPedido(pedido,'compartilhar'))return;setOcupado(true);setErro('');try{const arquivo=await obterArquivo(pedido,formato);if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[arquivo]}))){await navigator.share({title:`Pedido ${pedido.number}`,text:`Pedido de compra para ${pedido.supplierName}`,files:[arquivo]});await api(`/quotations/${id}/orders/${pedido.id}/shared`,{method:'POST'});await atualizarCompra();setMensagem('Compartilhamento do pedido registrado.')}else{const url=URL.createObjectURL(arquivo);const a=document.createElement('a');a.href=url;a.download=arquivo.name;a.click();URL.revokeObjectURL(url);setMensagem(`O navegador não compartilha arquivos. ${formato==='pdf'?'O PDF foi baixado':'A imagem foi baixada'} para você enviar manualmente.`)}}catch(e){if((e as DOMException)?.name!=='AbortError')setErro(mensagemErro(e,'Não foi possível compartilhar o pedido.'))}finally{setOcupado(false)}}
  const abrirOpcoesPedidoMinimo=async(responseId:number)=>{setOcupado(true);setErro('');try{setOpcoesMinimo(await api<OpcoesPedidoMinimo>(`/quotations/${id}/minimum-order-options/${responseId}`))}catch(e){setErro(mensagemErro(e,'Não foi possível calcular as alternativas para o pedido mínimo.'))}finally{setOcupado(false)}}
  const aplicarOpcaoPedidoMinimo=async(strategy:EstrategiaPedidoMinimo)=>{if(!opcoesMinimo)return;const texto=strategy==='ATINGIR_MINIMO'?'aplicar os ajustes sugeridos para atingir o mínimo':'repassar o pedido inteiro para as próximas ofertas';if(!window.confirm(`Deseja ${texto}? Pedidos já gerados serão atualizados.`))return;setOcupado(true);setErro('');try{const resultado=await api<{message:string;comparison:ComparacaoCotacao}>(`/quotations/${id}/minimum-order-options/${opcoesMinimo.responseId}/apply`,{method:'POST',body:JSON.stringify({strategy})});setComparacao(resultado.comparison);const[o,h]=await Promise.all([api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setPedidos(o);setHistorico(h);setMensagem(`${resultado.message} Você pode desfazer esta alteração.`);setOpcoesMinimo(null)}catch(e){setErro(mensagemErro(e,'Não foi possível aplicar a alternativa.'))}finally{setOcupado(false)}}
  const reincluirDistribuidora=async(responseId:number)=>{if(!window.confirm('Reincluir esta distribuidora na compra sugerida e recalcular o plano?'))return;setOcupado(true);setErro('');try{setComparacao(await api<ComparacaoCotacao>(`/quotations/${id}/responses/${responseId}/purchase-inclusion`,{method:'PUT',body:JSON.stringify({included:true})}));const[o,h]=await Promise.all([api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setPedidos(o);setHistorico(h);setMensagem('Distribuidora reincluída. Você pode desfazer ou consultar o histórico.')}catch(e){setErro(mensagemErro(e,'Não foi possível reincluir a distribuidora.'))}finally{setOcupado(false)}}
  const desfazerPlano=async()=>{if(!window.confirm('Desfazer a última alteração e restaurar exatamente o plano anterior?'))return;setOcupado(true);setErro('');try{const resultado=await api<ResultadoRestauracaoPlano>(`/quotations/${id}/purchase-plan/undo`,{method:'POST'});setComparacao(resultado.comparison);setHistorico(resultado.history);setPedidos(await api<PedidoCompra[]>(`/quotations/${id}/orders`));setMensagem(resultado.message)}catch(e){setErro(mensagemErro(e,'Não foi possível desfazer a alteração.'))}finally{setOcupado(false)}}
  const restaurarVersao=async(versao:VersaoPlano)=>{if(!window.confirm(`Restaurar a versão ${versao.number}? O estado atual continuará disponível no histórico.`))return;setOcupado(true);setErro('');try{const resultado=await api<ResultadoRestauracaoPlano>(`/quotations/${id}/purchase-plan/versions/${versao.id}/restore`,{method:'POST'});setComparacao(resultado.comparison);setHistorico(resultado.history);setPedidos(await api<PedidoCompra[]>(`/quotations/${id}/orders`));setMensagem(resultado.message);setHistoricoAberto(false)}catch(e){setErro(mensagemErro(e,'Não foi possível restaurar esta versão.'))}finally{setOcupado(false)}}
  const abrirAjusteManual=()=>{if(!opcoesMinimo)return;setAjusteManual(opcoesMinimo);setOpcoesMinimo(null)}
  const salvarAjusteManual=async(itens:EdicaoPlano[],baseVersionId:number)=>{setOcupado(true);setErro('');try{setComparacao(await api<ComparacaoCotacao>(`/quotations/${id}/purchase-plan`,{method:'PUT',body:JSON.stringify({items:itens,baseVersionId})}));const[o,h]=await Promise.all([api<PedidoCompra[]>(`/quotations/${id}/orders`),api<HistoricoPlano>(`/quotations/${id}/purchase-plan/history`)]);setPedidos(o);setHistorico(h);setAjusteManual(null);setMensagem('Ajustes aplicados produto por produto. Você pode desfazer ou consultar o histórico.')}catch(e){setErro(mensagemErro(e,'Não foi possível salvar os ajustes manuais.'))}finally{setOcupado(false)}}
  const finalizar=async()=>{if(!comparacao||finalizando.current)return;const parcial=comparacao.productsWithoutOffer>0||comparacao.partiallyCoveredProducts>0;if(parcial&&!window.confirm('Existem produtos sem cobertura. Deseja finalizar mesmo assim?'))return;finalizando.current=true;setOcupado(true);setErro('');try{await api(`/quotations/${id}/complete`,{method:'POST',body:JSON.stringify({confirmPartialCoverage:parcial})});await carregar();setMensagem('Compra finalizada.')}catch(e){setErro(mensagemErro(e,'Não foi possível finalizar a compra.'))}finally{finalizando.current=false;setOcupado(false)}}
  const abrirProrrogacao=()=>{if(!cotacao)return;setNovoPrazo(prazoLocalMais24Horas(cotacao.expiresAt));setProrrogando(true)}
  const prorrogar=async()=>{const data=new Date(novoPrazo);if(!novoPrazo||Number.isNaN(data.getTime())){setErro('Informe uma nova data e hora para o prazo.');return}setOcupado(true);setErro('');try{const atualizada=await api<Cotacao>(`/quotations/${id}/expiration`,{method:'PUT',body:JSON.stringify({expiresAt:data.toISOString()})});setProrrogando(false);setLinkProrrogado(true);await carregar();setMensagem(`Cotação prorrogada até ${date(atualizada.expiresAt)}. Reenvie o link para atualizar a prévia no WhatsApp.`)}catch(e){setErro(mensagemErro(e,'Não foi possível prorrogar a cotação.'))}finally{setOcupado(false)}}
  const alternarDistribuidora=(chave:string)=>setExpandidas(a=>{const n=new Set(a);if(n.has(chave))n.delete(chave);else n.add(chave);return n})
  if(carregando)return <div className="page"><Carregando/></div>;if(!cotacao)return <div className="page"><AvisoErro message={erro||'Cotação não encontrada.'}/></div>
  const mensagemLink=cotacao.publicUrl?`Olá! Estamos realizando uma nova cotação.\n${cotacao.publicUrl}`:'';const podeEditar=!!user&&['ADMIN','BUYER'].includes(user.role)&&cotacao.status==='CLOSED';const podeGerenciar=!!user&&['ADMIN','BUYER'].includes(user.role)&&['DRAFT','OPEN','CLOSED'].includes(cotacao.status);const itensAtivos=cotacao.items.filter(item=>item.active)
  return <div className="page"><div className="back-row"><LinkInterno to="/cotacoes" className="text-link"><ArrowLeft/>Voltar para cotações</LinkInterno></div><div className="detail-header"><div><div className="title-line"><h1>{cotacao.name}</h1><EtiquetaStatus status={cotacao.status}/></div><p>Criada em {date(cotacao.createdAt)} · {itensAtivos.length} produtos ativos{itensAtivos.length!==cotacao.items.length?` de ${cotacao.items.length}`:''} · Prazo: {date(cotacao.expiresAt)}</p></div><div className="header-actions"><button className="button button-ghost" onClick={()=>void carregar()}><RefreshCw/>Atualizar</button>{cotacao.status==='DRAFT'&&<button className="button button-primary" disabled={ocupado} onClick={()=>void acao('open')}><Send/>Abrir cotação</button>}{(cotacao.status==='OPEN'||cotacao.status==='CLOSED')&&<button className="button button-secondary" disabled={ocupado} onClick={abrirProrrogacao}><Clock3/>Prorrogar</button>}{cotacao.status==='OPEN'&&<button className="button button-danger-soft" disabled={ocupado} onClick={()=>void acao('close')}><Lock/>Fechar cotação</button>}{cotacao.status==='CLOSED'&&<button className="button button-primary" disabled={ocupado} onClick={()=>void finalizar()}><CheckCircle2/>Finalizar compra</button>}</div></div>{erro&&<AvisoErro message={erro}/>} {mensagem&&<div className="alert alert-success">{mensagem}</div>}{cotacao.publicUrl&&<section className="share-strip"><div><div className="share-strip-icon"><Link2/></div><div><strong>Link para representantes</strong><span>{cotacao.publicUrl}</span></div></div><div>{linkProrrogado&&<button className="button button-primary" onClick={()=>window.open(`https://wa.me/?text=${encodeURIComponent(mensagemLink)}`,'_blank','noopener,noreferrer')}><Share2/>Reenviar no WhatsApp</button>}<button className="button button-secondary" onClick={()=>void copiar(cotacao.publicUrl!,'link')}><Clipboard/>{copiado==='link'?'Copiado!':'Copiar link'}</button><button className="button button-ghost" onClick={()=>void copiar(mensagemLink,'message')}>{copiado==='message'?'Copiada!':'Copiar mensagem'}</button><a className="icon-button" title="Abrir link" href={cotacao.publicUrl} target="_blank"><ExternalLink/></a></div></section>}
    <div className="tabs"><button className={aba==='products'?'active':''} onClick={()=>setAba('products')}><PackageCheck/>Produtos <span>{itensAtivos.length}</span></button><button className={aba==='responses'?'active':''} onClick={()=>setAba('responses')}><Users/>Respostas <span>{respostas.filter(r=>r.status==='SUBMITTED'&&r.active).length}</span></button><button className={aba==='comparison'?'active':''} onClick={()=>setAba('comparison')}><CheckCircle2/>Comparativo</button><button className={aba==='purchase'?'active':''} onClick={()=>setAba('purchase')}><ShoppingCart/>Compra sugerida</button></div>
    {aba==='purchase'&&podeEditar&&historico.canUndo&&<div className="plan-undo-strip"><div><RotateCcw/><span><strong>Plano alterado</strong>{historico.versions[0]?.description}</span></div><div><button className="button button-secondary" disabled={ocupado} onClick={()=>void desfazerPlano()}>Desfazer última alteração</button><button className="button button-ghost" onClick={()=>setHistoricoAberto(true)}><History/>Ver histórico</button></div></div>}
    {aba==='products'&&<Produtos cotacao={cotacao} podeEditar={podeGerenciar} ocupado={ocupado} aoSalvar={atualizarItem}/>} {aba==='responses'&&<Respostas respostas={respostas} total={itensAtivos.length} podeEditar={podeGerenciar} ocupado={ocupado} aoAlternar={(resposta,active)=>void atualizarRespostaAtiva(resposta,active)}/>} {aba==='comparison'&&comparacao&&<Comparativo comparacao={comparacao}/>} {aba==='purchase'&&comparacao&&<CompraSugerida comparacao={comparacao} pedidos={pedidos} expandidas={expandidas} podeEditar={podeEditar} ocupado={ocupado} aoAlternar={alternarDistribuidora} aoTrocar={setProdutoTroca} aoEditarPlano={abrirPlano} aoEditarProduto={abrirProdutoPlano} aoGerar={id=>void gerarPedido(id)} aoBaixar={(p,f)=>void baixar(p,f)} aoCompartilhar={(p,f)=>void compartilhar(p,f)} aoVerMinimo={id=>void abrirOpcoesPedidoMinimo(id)} aoReincluir={id=>void reincluirDistribuidora(id)} aoHistorico={()=>setHistoricoAberto(true)}/>} {produtoTroca&&<ModalTroca produto={produtoTroca} ocupado={ocupado} aoFechar={()=>setProdutoTroca(null)} aoEscolher={r=>void escolherCampeao(produtoTroca.quotationItemId,r)} aoAutomatico={()=>void voltarAutomatico(produtoTroca.quotationItemId)}/>} {edicoes&&comparacao&&<ModalPlano produtos={produtoPlano==null?comparacao.products:comparacao.products.filter(p=>p.quotationItemId===produtoPlano)} edicoes={edicoes} setEdicoes={setEdicoes} erros={errosPlano} ocupado={ocupado} focado={produtoPlano!=null} aoFechar={()=>{setEdicoes(null);setProdutoPlano(null)}} aoSalvar={()=>void salvarPlano()}/>} {prorrogando&&<ModalProrrogar prazo={novoPrazo} ocupado={ocupado} aoAlterar={setNovoPrazo} aoFechar={()=>setProrrogando(false)} aoSalvar={()=>void prorrogar()}/>} {opcoesMinimo&&<ModalPedidoMinimo opcoes={opcoesMinimo} ocupado={ocupado} aoFechar={()=>setOpcoesMinimo(null)} aoAplicar={strategy=>void aplicarOpcaoPedidoMinimo(strategy)} aoManual={abrirAjusteManual}/>} {ajusteManual&&comparacao&&<ModalAjusteMinimoManual cotacaoId={id!} opcoes={ajusteManual} comparacao={comparacao} baseVersionId={historico.currentVersionId} ocupado={ocupado} aoFechar={()=>setAjusteManual(null)} aoSalvar={(itens,base)=>void salvarAjusteManual(itens,base)}/>} {historicoAberto&&<ModalHistorico historico={historico} ocupado={ocupado} aoFechar={()=>setHistoricoAberto(false)} aoRestaurar={v=>void restaurarVersao(v)}/>} {/* fim dos modais */}
  </div>
}

function ModalProrrogar({prazo,ocupado,aoAlterar,aoFechar,aoSalvar}:{prazo:string;ocupado:boolean;aoAlterar:(prazo:string)=>void;aoFechar:()=>void;aoSalvar:()=>void}){
  return <div className="modal-backdrop"><section className="modal extension-modal"><div className="modal-header modal-header-simple"><div><h2>Prorrogar cotação</h2><p>A cotação ficará aberta para novas propostas até o prazo escolhido.</p></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div><label className="extension-date-field">Novo prazo<input type="datetime-local" value={prazo} onChange={event=>aoAlterar(event.target.value)} required/></label><p className="extension-note">O link será atualizado para o WhatsApp mostrar a nova data na prévia.</p><div className="modal-actions"><button className="button button-ghost" disabled={ocupado} onClick={aoFechar}>Cancelar</button><button className="button button-primary" disabled={ocupado||!prazo} onClick={aoSalvar}>{ocupado?'Prorrogando...':'Prorrogar e reabrir'}</button></div></section></div>
}

function ModalPedidoMinimo({opcoes,ocupado,aoFechar,aoAplicar,aoManual}:{opcoes:OpcoesPedidoMinimo;ocupado:boolean;aoFechar:()=>void;aoAplicar:(strategy:EstrategiaPedidoMinimo)=>void;aoManual:()=>void}){
  const atingir=opcoes.reachMinimum,repassar=opcoes.reallocateOrder
  return <div className="modal-backdrop"><section className="modal minimum-order-modal"><div className="modal-header modal-header-simple"><div><span className="eyebrow green">Pedido mínimo</span><h2>{opcoes.supplierName}</h2><p>O pedido atual soma {money(opcoes.currentTotal)} e precisa chegar a {money(opcoes.minimumOrderValue)}. Confira o impacto antes de alterar o plano.</p></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div><div className="minimum-options">
    <article className={atingir.feasible?'':'option-unavailable'}><div className="minimum-option-title"><div><strong>Atingir o mínimo</strong><span>Realoca produtos primeiro e só depois adiciona unidades extras.</span></div><span className={atingir.feasible?'status-active':'status-inactive'}>{atingir.feasible?'Disponível':'Não foi possível'}</span></div>{atingir.adjustments.length>0&&<div className="minimum-adjustments">{atingir.adjustments.map(item=><div key={`${item.quotationItemId}-${item.type}`}><div><strong>{item.productName}</strong><span>{item.type==='UNIDADES_EXTRAS'?`${item.extraQuantity} unidades extras`:`de ${item.currentQuantity} para ${item.projectedQuantity} un. nesta distribuidora`}</span></div><small>{money(item.unitPrice)} por un.</small></div>)}</div>}<div className="minimum-option-summary"><span>Novo pedido<strong>{money(atingir.projectedSupplierTotal)}</strong></span><span>Impacto no total<strong>{atingir.purchaseIncrease>=0?'+':''}{money(atingir.purchaseIncrease)}</strong></span><span>Unidades extras<strong>{atingir.extraUnits}</strong></span></div>{!atingir.feasible&&<p className="option-reason">O estoque informado não é suficiente para chegar ao mínimo sem prejudicar outro pedido.</p>}<button className="button button-primary full-button" disabled={ocupado||!atingir.feasible} onClick={()=>aoAplicar('ATINGIR_MINIMO')}>Aplicar ajuste para atingir o mínimo</button></article>
    <article className={repassar.feasible?'':'option-unavailable'}><div className="minimum-option-title"><div><strong>Repassar pedido inteiro</strong><span>Retira esta distribuidora do plano e usa as próximas melhores ofertas.</span></div><span className={repassar.feasible?'status-active':'status-inactive'}>{repassar.feasible?'Disponível':'Sem cobertura total'}</span></div>{repassar.adjustments.length>0&&<div className="minimum-adjustments">{repassar.adjustments.map(item=><div key={item.quotationItemId}><div><strong>{item.productName}</strong><span>{item.currentQuantity} un. → {item.destinationSupplier??'sem outra oferta'}</span></div></div>)}</div>}<div className="minimum-option-summary"><span>Novo total geral<strong>{money(repassar.projectedPurchaseTotal)}</strong></span><span>Impacto no total<strong>{repassar.purchaseIncrease>=0?'+':''}{money(repassar.purchaseIncrease)}</strong></span><span>Novas sem cobertura<strong>{repassar.uncoveredUnits} un.</strong></span></div>{!repassar.feasible&&<p className="option-reason">Não há estoque suficiente nas outras propostas para repassar tudo.</p>}<button className="button button-danger-soft full-button" disabled={ocupado||!repassar.feasible} onClick={()=>aoAplicar('REPASSAR_PEDIDO')}>Repassar para outras distribuidoras</button></article>
  </div><div className="minimum-manual-entry"><div><SlidersHorizontal/><span><strong>Prefere decidir com calma?</strong>Ajuste fornecedor e quantidade de cada produto e veja quanto falta em tempo real.</span></div><button className="button button-secondary" disabled={ocupado} onClick={aoManual}>Ajustar produto por produto</button></div><div className="modal-actions"><button className="button button-ghost" disabled={ocupado} onClick={aoFechar}>Cancelar</button></div></section></div>
}

function ModalHistorico({historico,ocupado,aoFechar,aoRestaurar}:{historico:HistoricoPlano;ocupado:boolean;aoFechar:()=>void;aoRestaurar:(versao:VersaoPlano)=>void}){
  return <div className="modal-backdrop"><section className="modal plan-history-modal"><div className="modal-header modal-header-simple"><div><span className="eyebrow green">Plano de compra</span><h2>Histórico de alterações</h2><p>Restaure fornecedores, quantidades e distribuidoras exatamente como estavam em qualquer versão compatível.</p></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div>
    {historico.versions.length===0?<EstadoVazio title="Nenhuma alteração registrada" description="A primeira versão será criada quando o plano for alterado."/>:<div className="plan-history-list">{historico.versions.map(versao=><article key={versao.id} className={versao.current?'current':''}><div className="history-version-number"><span>v{versao.number}</span>{versao.current&&<small>Atual</small>}</div><div className="history-version-content"><strong>{versao.description}</strong><span>{date(versao.createdAt)} · {versao.createdBy}</span>{!versao.restorable&&versao.blockedReason&&<small className="history-blocked"><AlertTriangle/>{versao.blockedReason}</small>}</div><strong>{money(versao.total)}</strong>{!versao.current&&<button className="button button-secondary" disabled={ocupado||!versao.restorable} onClick={()=>aoRestaurar(versao)}>{versao.restorable?'Restaurar':'Indisponível'}</button>}</article>)}</div>}
    <div className="modal-actions"><button className="button button-ghost" onClick={aoFechar}>Fechar</button></div>
  </section></div>
}

function ModalAjusteMinimoManual({cotacaoId,opcoes,comparacao,baseVersionId,ocupado,aoFechar,aoSalvar}:{cotacaoId:string;opcoes:OpcoesPedidoMinimo;comparacao:ComparacaoCotacao;baseVersionId:number;ocupado:boolean;aoFechar:()=>void;aoSalvar:(itens:EdicaoPlano[],baseVersionId:number)=>void}){
  const criarEdicoes=()=>comparacao.products.map(p=>({quotationItemId:p.quotationItemId,desiredQuantity:p.desiredQuantity,selectedResponseId:p.selectedResponseId??null,championQuantity:p.championQuantity??null,stockOverrideNote:p.stockOverrideNote??'',manualSelection:!!p.manualSelection}))
  const[iniciais]=useState<EdicaoPlano[]>(criarEdicoes);const[edicoes,setEdicoes]=useState<EdicaoPlano[]>(criarEdicoes);const[previa,setPrevia]=useState<PreviaManualPedidoMinimo|null>(null);const[carregandoPrevia,setCarregandoPrevia]=useState(true);const[erroPrevia,setErroPrevia]=useState('');const[busca,setBusca]=useState('');const[expandido,setExpandido]=useState<number|null>(null)
  useEffect(()=>{let cancelado=false;setCarregandoPrevia(true);const timer=window.setTimeout(async()=>{try{const resultado=await api<PreviaManualPedidoMinimo>(`/quotations/${cotacaoId}/minimum-order-options/${opcoes.responseId}/manual-preview`,{method:'POST',body:JSON.stringify({items:edicoes,baseVersionId})});if(!cancelado){setPrevia(resultado);setErroPrevia('')}}catch(e){if(!cancelado){setErroPrevia(mensagemErro(e,'Não foi possível calcular esta combinação.'));setPrevia(null)}}finally{if(!cancelado)setCarregandoPrevia(false)}},250);return()=>{cancelado=true;window.clearTimeout(timer)}},[cotacaoId,opcoes.responseId,edicoes,baseVersionId])
  const alterar=(itemId:number,parcial:Partial<EdicaoPlano>)=>setEdicoes(atuais=>atuais.map(item=>item.quotationItemId===itemId?{...item,...parcial}:item))
  const restaurarItem=(itemId:number)=>{const original=iniciais.find(item=>item.quotationItemId===itemId);if(original)alterar(itemId,{...original})}
  const grupoBase=comparacao.suggestedPurchase.find(g=>g.responseId===opcoes.responseId);const grupoProjetado=previa?.comparison.suggestedPurchase.find(g=>g.responseId===opcoes.responseId)
  const quantidade=(grupo:typeof grupoBase,itemId:number)=>grupo?.items?.find(item=>item.quotationItemId===itemId)?.allocatedQuantity??0
  const termo=busca.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();const incluidos=new Set(comparacao.supplierTotals.filter(s=>s.includedInSuggestedPurchase).map(s=>s.responseId))
  const candidatos=comparacao.products.filter(p=>p.offers.some(o=>o.responseId===opcoes.responseId)&&(!termo||`${p.productName} ${p.ean??''}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(termo))).sort((a,b)=>{const qa=quantidade(grupoBase,a.quotationItemId),qb=quantidade(grupoBase,b.quotationItemId);return qb-qa||a.productName.localeCompare(b.productName,'pt-BR')})
  const mudou=JSON.stringify(edicoes)!==JSON.stringify(iniciais);const total=previa?.supplierTotal??opcoes.currentTotal;const falta=previa?.shortfall??opcoes.shortfall
  return <div className="modal-backdrop"><section className="modal manual-minimum-modal"><div className="modal-header modal-header-simple"><div><span className="eyebrow green">Ajuste produto por produto</span><h2>{opcoes.supplierName}</h2><p>Altere apenas o que fizer sentido. Nada será salvo até sua confirmação final.</p></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div>
    <div className={`manual-minimum-summary ${falta>0?'warning':'complete'}`}><div><span>Total nesta distribuidora</span><strong>{money(total)}</strong></div><div><span>Pedido mínimo</span><strong>{money(opcoes.minimumOrderValue)}</strong></div><div><span>{falta>0?'Ainda falta':'Situação'}</span><strong>{falta>0?money(falta):'Mínimo atingido'}</strong></div><div><span>Impacto geral</span><strong>{previa?`${previa.purchaseIncrease>=0?'+':''}${money(previa.purchaseIncrease)}`:'Calculando...'}</strong></div><div><span>Unidades extras</span><strong>{previa?.extraUnits??0}</strong></div><div><span>Novas sem cobertura</span><strong>{previa?.uncoveredUnits??0}</strong></div></div>
    <div className="manual-minimum-search"><Search/><input type="search" placeholder="Buscar produto ou EAN" value={busca} onChange={e=>setBusca(e.target.value)}/><span>{candidatos.length} produtos</span></div>
    {erroPrevia&&<div className="alert alert-error">{erroPrevia}</div>}<div className="manual-minimum-products">{candidatos.map(produto=>{const edicao=edicoes.find(item=>item.quotationItemId===produto.quotationItemId)!;const original=iniciais.find(item=>item.quotationItemId===produto.quotationItemId)!;const aberto=expandido===produto.quotationItemId;const alterado=JSON.stringify(edicao)!==JSON.stringify(original);const ofertas=produto.offers.filter(o=>incluidos.has(o.responseId));const selecionada=ofertas.find(o=>o.responseId===edicao.selectedResponseId);const atual=quantidade(grupoBase,produto.quotationItemId),projetada=quantidade(grupoProjetado,produto.quotationItemId);const excesso=selecionada&&edicao.championQuantity!=null&&edicao.championQuantity>selecionada.availableQuantity;return <article key={produto.quotationItemId} className={alterado?'changed':''}><button type="button" className="manual-product-toggle" onClick={()=>setExpandido(aberto?null:produto.quotationItemId)}><div><strong>{produto.productName}</strong><span>{atual} un. antes → <b>{projetada} un. na prévia</b></span></div><span>{money(produto.offers.find(o=>o.responseId===opcoes.responseId)?.unitPrice)}</span><ChevronDown/></button>{aberto&&<div className="manual-product-fields"><label>Quantidade total que deseja comprar<input type="number" min="0" inputMode="numeric" value={edicao.desiredQuantity===0?'':edicao.desiredQuantity} placeholder="0" onChange={e=>{const valor=Math.max(0,Number(e.target.value));alterar(produto.quotationItemId,{desiredQuantity:valor,championQuantity:edicao.championQuantity==null?null:Math.min(edicao.championQuantity,valor),selectedResponseId:valor===0?null:edicao.selectedResponseId,manualSelection:valor===0?false:edicao.manualSelection})}}/></label><label>Comprar primeiro de<select value={edicao.manualSelection?edicao.selectedResponseId??'':''} disabled={edicao.desiredQuantity===0} onChange={e=>{if(!e.target.value){alterar(produto.quotationItemId,{selectedResponseId:produto.offers[0]?.responseId??null,championQuantity:null,manualSelection:false,stockOverrideNote:''});return}const responseId=Number(e.target.value),oferta=ofertas.find(o=>o.responseId===responseId);alterar(produto.quotationItemId,{selectedResponseId:responseId,manualSelection:true,championQuantity:Math.min(edicao.desiredQuantity,oferta?.availableQuantity??edicao.desiredQuantity),stockOverrideNote:''})}}><option value="">Automático — menor preço</option>{ofertas.map(oferta=><option key={oferta.responseId} value={oferta.responseId}>{oferta.supplierName} — {money(oferta.unitPrice)} · {oferta.availableQuantity} un.</option>)}</select></label><label>Quantidade nesta distribuidora<input type="number" min="1" max={edicao.desiredQuantity} disabled={!edicao.manualSelection||!edicao.selectedResponseId||edicao.desiredQuantity===0} value={edicao.manualSelection?edicao.championQuantity??'':''} placeholder="Automática" onChange={e=>alterar(produto.quotationItemId,{championQuantity:e.target.value?Number(e.target.value):null})}/></label>{excesso&&<label className="manual-stock-note">Justificativa do estoque adicional<input placeholder="Ex.: confirmado pelo representante" value={edicao.stockOverrideNote} onChange={e=>alterar(produto.quotationItemId,{stockOverrideNote:e.target.value})}/></label>}<div className="manual-product-actions"><button type="button" className="button button-secondary" onClick={()=>{const oferta=ofertas.find(o=>o.responseId===opcoes.responseId);if(oferta)alterar(produto.quotationItemId,{selectedResponseId:opcoes.responseId,manualSelection:true,championQuantity:Math.min(edicao.desiredQuantity,oferta.availableQuantity),stockOverrideNote:''})}}>Comprar de {opcoes.supplierName}</button>{alterado&&<button type="button" className="button button-ghost" onClick={()=>restaurarItem(produto.quotationItemId)}><RotateCcw/>Desfazer neste item</button>}</div></div>}</article>})}</div>
    <div className="manual-minimum-footer-note">{falta>0?<><AlertTriangle/><span>O plano continuará {money(falta)} abaixo do mínimo. Você ainda pode salvar e assumir o risco depois.</span></>:<><CheckCircle2/><span>O mínimo foi atingido nesta prévia.</span></>}</div><div className="modal-actions"><button className="button button-ghost" disabled={ocupado} onClick={aoFechar}>Cancelar sem salvar</button><button className="button button-primary" disabled={ocupado||carregandoPrevia||!!erroPrevia||!mudou} onClick={()=>{if(window.confirm(`Aplicar todos os ajustes? O pedido ficará em ${money(total)}${falta>0?`, ainda ${money(falta)} abaixo do mínimo`:''}.`))aoSalvar(edicoes,baseVersionId)}}>{ocupado?'Salvando...':falta>0?'Salvar mesmo abaixo do mínimo':'Aplicar ajustes'}</button></div>
  </section></div>
}

function Produtos({cotacao,podeEditar,ocupado,aoSalvar}:{cotacao:Cotacao;podeEditar:boolean;ocupado:boolean;aoSalvar:(itemId:number,quantity:number,active:boolean)=>Promise<void>}){return <section className="card"><div className="card-header"><div><h2>Produtos solicitados</h2><p>Altere a quantidade ou desative produtos sem apagar o histórico da cotação.</p></div></div><div className="table-wrap"><table><thead><tr><th>#</th><th>Produto</th><th>EAN</th><th>Quantidade</th><th>Status</th>{podeEditar&&<th/>}</tr></thead><tbody>{cotacao.items.map((item,n)=><LinhaProduto key={item.id} item={item} numero={n+1} podeEditar={podeEditar} ocupado={ocupado} aoSalvar={aoSalvar}/>)}</tbody></table></div></section>}
function LinhaProduto({item,numero,podeEditar,ocupado,aoSalvar}:{item:Cotacao['items'][number];numero:number;podeEditar:boolean;ocupado:boolean;aoSalvar:(itemId:number,quantity:number,active:boolean)=>Promise<void>}){const[quantityInput,setQuantityInput]=useState(String(item.requestedQuantity));const[active,setActive]=useState(item.active);useEffect(()=>{setQuantityInput(String(item.requestedQuantity));setActive(item.active)},[item]);const quantity=quantityInput.trim()===''?null:Number(quantityInput);const quantidadeValida=quantity!==null&&Number.isInteger(quantity)&&quantity>=1;const mudou=(quantidadeValida&&quantity!==item.requestedQuantity)||active!==item.active;return <tr className={active?'':'inactive-row'}><td>{numero}</td><td><strong>{item.productName}</strong>{!active&&<small className="inactive-note">Fora da cotação</small>}</td><td>{item.ean??'—'}</td><td>{podeEditar?<input className="quotation-quantity-input" type="number" min="1" step="1" value={quantityInput} onChange={event=>setQuantityInput(event.target.value)}/>:<>{item.requestedQuantity} un.</>}</td><td><span className={active?'status-active':'status-inactive'}>{active?'Ativo':'Desativado'}</span></td>{podeEditar&&<td><div className="quotation-item-actions"><label className="active-toggle"><input type="checkbox" checked={active} onChange={event=>setActive(event.target.checked)}/><span>{active?'Ativo na cotação':'Inativo'}</span></label><button className="button button-secondary" disabled={ocupado||!mudou||!quantidadeValida} onClick={()=>{if(quantidadeValida)void aoSalvar(item.id,quantity,active)}}><Save/>Salvar</button></div></td>}</tr>}
function Respostas({respostas,total,podeEditar,ocupado,aoAlternar}:{respostas:RespostaCotacao[];total:number;podeEditar:boolean;ocupado:boolean;aoAlternar:(resposta:RespostaCotacao,active:boolean)=>void}){return <section className="card"><div className="card-header"><div><h2>Respostas dos representantes</h2><p>Consulte também o valor mínimo informado por cada distribuidora.</p></div></div>{respostas.length===0?<EstadoVazio title="Nenhuma resposta ainda" description="Compartilhe o link com seus representantes."/>:<div className="table-wrap"><table><thead><tr><th>Distribuidora</th><th>Representante</th><th>Status</th><th>Envio</th><th>Itens</th><th>Total</th><th>Pedido mínimo</th>{podeEditar&&<th/>}</tr></thead><tbody>{respostas.map(r=><tr key={r.id} className={r.active?'':'inactive-row'}><td><strong>{r.supplierName}</strong>{!r.active&&<small className="inactive-note">Ignorada nos cálculos</small>}{r.active&&!r.includedInSuggestedPurchase&&<small className="inactive-note">Repassada para outras ofertas</small>}</td><td>{r.representativeName}</td><td><EtiquetaStatus status={r.status}/></td><td>{r.submittedAt?date(r.submittedAt):<Clock3/>}</td><td>{r.quotedItems} de {total}</td><td>{money(r.total)}</td><td>{r.minimumOrderValue==null?'Sem mínimo':money(r.minimumOrderValue)}</td>{podeEditar&&<td><button className={`button ${r.active?'button-danger-soft':'button-secondary'}`} disabled={ocupado} onClick={()=>aoAlternar(r,!r.active)}><Power/>{r.active?'Desativar':'Reativar'}</button></td>}</tr>)}</tbody></table></div>}</section>}
function Comparativo({comparacao}:{comparacao:ComparacaoCotacao}){
  const[busca,setBusca]=useState('');const[ordem,setOrdem]=useState<'menor'|'maior'|'economia'>('menor')
  const normalizar=(valor:string)=>valor.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase()
  const termo=normalizar(busca.trim())
  const detalhes=comparacao.products.map(produto=>{const precos=produto.offers.map(oferta=>oferta.unitPrice);const menor=precos.length?Math.min(...precos):null;const maior=precos.length?Math.max(...precos):null;const economia=menor!==null&&maior!==null?(maior-menor)*produto.requestedQuantity:0;return{produto,menor,maior,economia}}).filter(({produto})=>!termo||normalizar(`${produto.productName} ${produto.ean??''}`).includes(termo)).sort((a,b)=>ordem==='maior'?(b.maior??-1)-(a.maior??-1):ordem==='economia'?b.economia-a.economia:(a.menor??Number.MAX_SAFE_INTEGER)-(b.menor??Number.MAX_SAFE_INTEGER))
  return <section className="card comparison-card"><div className="card-header"><div><h2>Comparativo de preços</h2><p>Veja a faixa de preço e a economia potencial de cada produto.</p></div></div>{comparacao.supplierTotals.length===0?<EstadoVazio title="Aguardando propostas" description="O comparativo será preenchido após o primeiro envio."/>:<><div className="comparison-controls"><div className="comparison-search"><Search/><input type="search" placeholder="Buscar produto ou EAN" value={busca} onChange={event=>setBusca(event.target.value)}/>{busca&&<button type="button" onClick={()=>setBusca('')} aria-label="Limpar busca">×</button>}</div><label>Ordenar por<select value={ordem} onChange={event=>setOrdem(event.target.value as typeof ordem)}><option value="menor">Menor preço</option><option value="maior">Maior preço</option><option value="economia">Maior economia</option></select></label><span>{detalhes.length} de {comparacao.products.length} produtos</span></div>{detalhes.length===0?<EstadoVazio title="Nenhum produto encontrado" description="Tente buscar por outro nome ou EAN."/>:<div className="table-wrap"><table className="comparison-table"><thead><tr><th>Produto</th><th>Qtd.</th>{comparacao.supplierTotals.map(s=><th key={s.responseId}>{s.supplierName}</th>)}<th>Faixa de preço</th><th>Economia</th><th>Melhor</th></tr></thead><tbody>{detalhes.map(({produto:p,menor,maior,economia})=><tr key={p.quotationItemId}><td><strong>{p.productName}</strong><small>{p.ean?`EAN ${p.ean}`:'Sem EAN'}</small></td><td>{p.requestedQuantity}</td>{comparacao.supplierTotals.map(s=>{const o=p.offers.find(x=>x.responseId===s.responseId);return <td key={s.responseId} className={o?.bestPrice?'best-cell':''}>{o?<><strong>{money(o.unitPrice)}</strong><small>{o.availableQuantity} un.</small></>:<>—</>}</td>})}<td>{menor===null?'—':<div className="comparison-metric"><strong>{money(menor)}</strong><small>menor · até {money(maior!)}</small></div>}</td><td>{economia>0?<div className="comparison-metric savings"><strong>{money(economia)}</strong><small>vs. maior preço</small></div>:'—'}</td><td>{p.winningSupplier??'Sem oferta'}</td></tr>)}</tbody></table></div>}</>}</section>}

function CompraSugerida({comparacao,pedidos,expandidas,podeEditar,ocupado,aoAlternar,aoTrocar,aoEditarPlano,aoEditarProduto,aoGerar,aoBaixar,aoCompartilhar,aoVerMinimo,aoReincluir,aoHistorico}:{comparacao:ComparacaoCotacao;pedidos:PedidoCompra[];expandidas:Set<string>;podeEditar:boolean;ocupado:boolean;aoAlternar:(c:string)=>void;aoTrocar:(p:ComparacaoProduto)=>void;aoEditarPlano:()=>void;aoEditarProduto:(p:ComparacaoProduto)=>void;aoGerar:(id:number)=>void;aoBaixar:(p:PedidoCompra,f:FormatoPedido)=>void;aoCompartilhar:(p:PedidoCompra,f:FormatoPedido)=>void;aoVerMinimo:(id:number)=>void;aoReincluir:(id:number)=>void;aoHistorico:()=>void}){
  const excluidas=comparacao.supplierTotals.filter(item=>!item.includedInSuggestedPurchase)
  const abaixo=comparacao.suggestedPurchase.filter(item=>item.minimumOrderStatus==='ABAIXO_DO_MINIMO').length
  return <div className="purchase-layout"><section className="card"><div className="card-header purchase-card-header"><div><h2>Plano final de compra</h2><p>O sistema começa pela melhor oferta e avisa quando o pedido não atende ao mínimo da distribuidora.</p></div>{podeEditar&&<div className="purchase-header-actions"><button className="button button-ghost" onClick={aoHistorico}><History/>Histórico do plano</button><button className="button button-secondary" onClick={aoEditarPlano}><Edit3/>Revisar todos os produtos</button></div>}</div>
    <div className="purchase-guide" aria-label="Como concluir a compra"><div><span>1</span><p><strong>Confira a divisão</strong>Abra cada distribuidora e confira pedido e valor mínimo.</p></div><div><span>2</span><p><strong>Resolva os alertas</strong>Ajuste o mínimo ou repasse às próximas ofertas.</p></div><div><span>3</span><p><strong>Gere os pedidos</strong>Confirme explicitamente se decidir comprar abaixo do mínimo.</p></div></div>
    {comparacao.suggestedPurchase.length===0?<EstadoVazio title="Ainda não há uma compra sugerida" description="Receba ao menos uma proposta ou aumente uma quantidade final."/>:<><div className="supplier-cards expandable">{comparacao.suggestedPurchase.map(d=>{const chave=String(d.responseId??d.supplierName),aberta=expandidas.has(chave),itens=d.items??[],pedido=pedidos.find(p=>p.responseId===d.responseId),abaixoMinimo=d.minimumOrderStatus==='ABAIXO_DO_MINIMO';return <article className={`supplier-purchase-card ${aberta?'expanded':''} ${abaixoMinimo?'below-minimum':''}`} key={chave}><button className="supplier-card supplier-toggle" aria-expanded={aberta} onClick={()=>aoAlternar(chave)}><div className="supplier-initial">{d.supplierName[0]}</div><div><strong>{d.supplierName}</strong><span>{d.productCount} produtos · {d.totalQuantity} unidades · {d.minimumOrderValue==null?'sem pedido mínimo':`mínimo ${money(d.minimumOrderValue)}`}</span></div><div className="supplier-order-total"><strong>{money(d.total)}</strong>{d.minimumOrderStatus==='ATENDIDO'&&<small>Mínimo atendido</small>}{abaixoMinimo&&<small>Faltam {money(d.minimumOrderShortfall)}</small>}</div><ChevronDown/></button>
      {abaixoMinimo&&<div className="minimum-order-alert"><AlertTriangle/><div><strong>Pedido abaixo do mínimo</strong><span>Esta distribuidora pode rejeitar o pedido. Faltam {money(d.minimumOrderShortfall)}.</span></div>{podeEditar&&d.responseId&&<button className="button button-secondary" disabled={ocupado} onClick={()=>aoVerMinimo(d.responseId!)}>Ver alternativas</button>}</div>}
      {aberta&&<div className="supplier-products">{itens.map(item=>{const produto=comparacao.products.find(p=>p.quotationItemId===item.quotationItemId);return <div className="allocated-product" key={`${chave}-${item.quotationItemId}`}><div><div className="allocation-title"><strong>{item.productName}</strong>{item.champion?<span className={`allocation-badge ${item.manualSelection?'manual':''}`}><Trophy/>{item.manualSelection?'Escolhida por você':'Melhor oferta'}</span>:<span className="allocation-badge complement">Complemento automático</span>}</div><span>{item.allocatedQuantity} un. × {money(item.unitPrice)} · {item.offerPosition}ª posição no preço</span>{item.stockOverrideNote&&<small className="stock-note">Estoque adicional confirmado internamente.</small>}</div><strong>{money(item.subtotal)}</strong>{item.champion&&produto&&podeEditar&&<div className="line-actions"><button className="button button-secondary" disabled={ocupado} onClick={()=>aoTrocar(produto)}><Trophy/>Trocar distribuidora</button><button className="button button-ghost" onClick={()=>aoEditarProduto(produto)}><Edit3/>Ajustar compra</button></div>}</div>})}{pedido?.belowMinimum&&<div className="generated-below-minimum"><AlertTriangle/>Pedido gerado abaixo do mínimo com confirmação do comprador.</div>}<div className="order-actions"><span className={`order-status status-${pedido?.status?.toLowerCase()??'novo'}`}>{pedido?.status??'PEDIDO NÃO GERADO'}</span>{podeEditar&&<button className="button button-secondary" disabled={ocupado} onClick={()=>d.responseId&&aoGerar(d.responseId)}><FileText/>{pedido?'Gerar novamente':'Gerar pedido'}</button>}{pedido?.pdfAvailable&&<><button className="button button-ghost" onClick={()=>aoBaixar(pedido,'pdf')}><Download/>PDF</button><button className="button button-ghost" onClick={()=>aoBaixar(pedido,'image')}><FileImage/>Imagem</button>{podeEditar&&<><button className="button button-primary" onClick={()=>aoCompartilhar(pedido,'pdf')}><Share2/>Compartilhar PDF</button><button className="button button-primary" onClick={()=>aoCompartilhar(pedido,'image')}><Share2/>Compartilhar imagem</button></>}</>}</div></div>}</article>})}</div><div className="composition-total"><span>Total do plano de compra</span><strong>{money(comparacao.bestCompositionTotal)}</strong></div></>}
    {excluidas.length>0&&<div className="excluded-suppliers"><strong>Distribuidoras repassadas</strong><p>Reincluir recalcula pelas ofertas atuais. Para recuperar exatamente o plano anterior, use Desfazer ou o Histórico.</p>{excluidas.map(item=><div key={item.responseId}><span>{item.supplierName}{item.minimumOrderValue!=null?` · mínimo ${money(item.minimumOrderValue)}`:''}</span>{podeEditar&&<button className="button button-ghost" disabled={ocupado} onClick={()=>aoReincluir(item.responseId)}>Reincluir</button>}</div>)}</div>}
    </section><aside className="purchase-summary"><div className="summary-highlight"><ShoppingCart/><span>Compra sugerida</span><strong>{money(comparacao.bestCompositionTotal)}</strong></div><div><span>Economia estimada</span><strong>{money(comparacao.estimatedSavings)}</strong></div><div className={abaixo>0?'summary-warning':''}><span>Pedidos abaixo do mínimo</span><strong>{abaixo}</strong></div><div><span>Produtos sem cobertura</span><strong>{comparacao.productsWithoutOffer+comparacao.partiallyCoveredProducts}</strong></div></aside></div>
}

type ParcelaPrevista={supplierName:string;quantity:number;position:number;principal:boolean}
function preverDivisao(produto:ComparacaoProduto,edicao:EdicaoPlano){
  const desejada=Math.max(0,edicao.desiredQuantity||0);const automatico=!edicao.manualSelection&&edicao.championQuantity==null
  const idPrincipal=automatico?produto.offers[0]?.responseId:edicao.selectedResponseId
  const principal=produto.offers.find(oferta=>oferta.responseId===idPrincipal);const parcelas:ParcelaPrevista[]=[]
  if(!principal||desejada===0)return{parcelas,restante:principal?0:desejada,automatico}
  const quantidadePrincipal=automatico?Math.min(desejada,principal.availableQuantity):Math.min(desejada,Math.max(0,edicao.championQuantity??Math.min(desejada,principal.availableQuantity)))
  if(quantidadePrincipal>0)parcelas.push({supplierName:principal.supplierName,quantity:quantidadePrincipal,position:principal.position,principal:true})
  let restante=desejada-quantidadePrincipal
  for(const oferta of produto.offers.filter(oferta=>oferta.responseId!==principal.responseId)){if(restante<=0)break;const quantidade=Math.min(restante,oferta.availableQuantity);if(quantidade>0)parcelas.push({supplierName:oferta.supplierName,quantity:quantidade,position:oferta.position,principal:false});restante-=quantidade}
  return{parcelas,restante,automatico}
}

function ModalPlano({produtos,edicoes,setEdicoes,erros,ocupado,focado,aoFechar,aoSalvar}:{produtos:ComparacaoProduto[];edicoes:EdicaoPlano[];setEdicoes:(e:EdicaoPlano[])=>void;erros:Record<string,string>;ocupado:boolean;focado:boolean;aoFechar:()=>void;aoSalvar:()=>void}){
  const[busca,setBusca]=useState('')
  const[modoEdicao,setModoEdicao]=useState<'rapido'|'avancado'>('rapido')
  const[edicoesIniciais]=useState(()=>edicoes.map(edicao=>({...edicao})))
  const alterar=(itemId:number,parcial:Partial<EdicaoPlano>)=>setEdicoes(edicoes.map(e=>e.quotationItemId===itemId?{...e,...parcial}:e))
  const termo=busca.normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim().toLowerCase()
  const produtosVisiveis=!termo?produtos:produtos.filter(produto=>`${produto.productName} ${produto.ean??''}`.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(termo))
  const temAlteracoes=JSON.stringify(edicoes)!==JSON.stringify(edicoesIniciais)
  const erroLocal=produtos.some(p=>{const e=edicoes.find(x=>x.quotationItemId===p.quotationItemId)!;const oferta=p.offers.find(o=>o.responseId===e.selectedResponseId);return e.desiredQuantity<0||(e.championQuantity!=null&&e.championQuantity>e.desiredQuantity)||(e.championQuantity!=null&&oferta&&e.championQuantity>oferta.availableQuantity&&!e.stockOverrideNote.trim())})
  return <div className="modal-backdrop"><section className={`modal purchase-plan-modal ${focado?'focused-plan-modal':''}`}>
    <div className="modal-header modal-header-simple"><div><h2>{focado?'Planejar compra deste produto':'Revisar plano final de compra'}</h2><p>{modoEdicao==='rapido'?'Escolha uma distribuidora e uma quantidade. O sistema aplicará o mesmo número ao total da compra e ao fornecedor escolhido.':focado?'Defina separadamente o total e como ele será dividido entre as distribuidoras.':'Revise cada produto e defina separadamente o total e a divisão entre distribuidoras.'}</p></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div>
    <div className="plan-mode-switch" role="tablist" aria-label="Modo de ajuste"><button type="button" role="tab" aria-selected={modoEdicao==='rapido'} className={modoEdicao==='rapido'?'active':''} onClick={()=>setModoEdicao('rapido')}><strong>Ajuste rápido</strong><span>Uma distribuidora e uma quantidade</span><small>Recomendado</small></button><button type="button" role="tab" aria-selected={modoEdicao==='avancado'} className={modoEdicao==='avancado'?'active':''} onClick={()=>setModoEdicao('avancado')}><strong>Avançado</strong><span>Divida a quantidade entre fornecedores</span></button></div>
    {modoEdicao==='rapido'?<div className="plan-intro quick-plan-intro"><strong>É bem simples</strong><span><b>1.</b> Escolha de quem vai comprar.</span><span><b>2.</b> Digite a quantidade. Ex.: 100 no total = 100 dessa distribuidora.</span></div>:<div className="plan-intro"><strong>Como funciona?</strong><span><b>1.</b> Defina o total que deseja comprar.</span><span><b>2.</b> Mantenha o cálculo automático ou escolha quem fornecerá primeiro.</span><span><b>3.</b> Se dividir a compra, informe quanto vai para a primeira distribuidora.</span></div>}
    {!focado&&<div className="plan-product-search"><Search/><input type="search" aria-label="Buscar produtos" placeholder="Buscar produto por nome ou EAN" value={busca} onChange={event=>setBusca(event.target.value)}/>{busca&&<button type="button" aria-label="Limpar busca" title="Limpar busca" onClick={()=>setBusca('')}><X/></button>}<span>{produtosVisiveis.length} de {produtos.length} produtos</span></div>}
    <div className="plan-items">{produtosVisiveis.length===0?<div className="plan-search-empty"><Search/><strong>Nenhum produto encontrado</strong><span>Tente buscar por outro nome ou EAN.</span><button type="button" className="button button-ghost" onClick={()=>setBusca('')}>Limpar busca</button></div>:produtosVisiveis.map(p=>{const e=edicoes.find(x=>x.quotationItemId===p.quotationItemId)!;const inicial=edicoesIniciais.find(x=>x.quotationItemId===p.quotationItemId)!;const produtoAlterado=JSON.stringify(e)!==JSON.stringify(inicial);const automatico=!e.manualSelection&&e.championQuantity==null;const idRapido=e.selectedResponseId??p.offers[0]?.responseId??null;const oferta=p.offers.find(o=>o.responseId===e.selectedResponseId)??p.offers[0];const quantidadeRapida=e.championQuantity??e.desiredQuantity;const excesso=e.championQuantity!=null&&oferta&&e.championQuantity>oferta.availableQuantity;const acimaDoTotal=e.championQuantity!=null&&e.championQuantity>e.desiredQuantity;const prefixo=`itens.${p.quotationItemId}.`;const previsao=preverDivisao(p,e);const primeira=previsao.parcelas[0];const complementos=previsao.parcelas.slice(1);const quantidadeComplementar=complementos.reduce((total,parcela)=>total+parcela.quantity,0);return <article key={p.quotationItemId} className="plan-item guided-plan-item">
      <div className="plan-product"><strong>{p.productName}</strong><span>Pedido original: {p.requestedQuantity} {p.requestedQuantity===1?'unidade':'unidades'}</span></div>
      {modoEdicao==='rapido'?<><div className="quick-plan-explanation"><strong>No ajuste rápido, os dois valores ficam iguais.</strong><span>Se informar 100 unidades, o total da compra será 100 e as 100 irão para a distribuidora escolhida.</span></div><div className="guided-fields quick-guided-fields">
        <div className="guided-field"><div className="guided-field-title"><span>1</span><div><label htmlFor={`distribuidora-rapida-${p.quotationItemId}`}>De qual distribuidora quer comprar?</label><small>Selecione quem receberá todo este produto no pedido.</small></div></div><select id={`distribuidora-rapida-${p.quotationItemId}`} value={idRapido??''} disabled={p.offers.length===0} onChange={x=>{const id=x.target.value?Number(x.target.value):null;alterar(p.quotationItemId,{selectedResponseId:id,manualSelection:!!id,championQuantity:id&&e.desiredQuantity>0?e.desiredQuantity:null,stockOverrideNote:''})}}><option value="">Selecione uma distribuidora</option>{p.offers.map(o=><option key={o.responseId} value={o.responseId}>{o.supplierName} — {money(o.unitPrice)} · estoque informado {o.availableQuantity} un.</option>)}</select>{p.offers.length===0&&<span className="guided-hint warning">Nenhuma distribuidora ofereceu este produto.</span>}</div>
        <div className="guided-field"><div className="guided-field-title"><span>2</span><div><label htmlFor={`quantidade-rapida-${p.quotationItemId}`}>Quantas unidades quer comprar dela?</label><small>Essa também será a quantidade total da compra.</small></div></div><input id={`quantidade-rapida-${p.quotationItemId}`} type="number" min="0" disabled={!idRapido} value={quantidadeRapida} onChange={x=>{const quantidade=Math.max(0,Number(x.target.value));const selecionada=p.offers.find(o=>o.responseId===idRapido);alterar(p.quotationItemId,{desiredQuantity:quantidade,selectedResponseId:quantidade>0?idRapido:null,manualSelection:quantidade>0&&!!idRapido,championQuantity:quantidade>0&&idRapido?quantidade:null,stockOverrideNote:selecionada&&quantidade<=selecionada.availableQuantity?'':e.stockOverrideNote})}}/><span className="guided-hint">Pedido original: {p.requestedQuantity} un.</span></div>
      </div>{produtoAlterado&&e.manualSelection&&e.championQuantity===e.desiredQuantity?<div className="quick-quantity-result"><span>Total que deseja comprar<strong>{e.desiredQuantity} un.</strong></span><b>=</b><span>Quantidade para {oferta?.supplierName??'a distribuidora'}<strong>{e.championQuantity} un.</strong></span></div>:<div className="quick-current-plan"><strong>Plano atual preservado</strong><span>{previsao.parcelas.length>1?`Hoje este produto está dividido entre ${previsao.parcelas.length} distribuidoras. Ao alterar a quantidade acima, o novo total irá inteiro para a distribuidora escolhida.`:'Digite uma nova quantidade para aplicar o ajuste rápido. Nada será alterado enquanto você não mudar um valor.'}</span></div>}</>:<div className="guided-fields">
        <div className="guided-field"><div className="guided-field-title"><span>1</span><div><label htmlFor={`quantidade-final-${p.quotationItemId}`}>Quanto deseja comprar no total?</label><small>Essa é a quantidade final que a farmácia receberá.</small></div></div><input id={`quantidade-final-${p.quotationItemId}`} type="number" min="0" value={e.desiredQuantity} onChange={x=>{const quantidade=Math.max(0,Number(x.target.value));alterar(p.quotationItemId,{desiredQuantity:quantidade,championQuantity:e.championQuantity!=null?Math.min(e.championQuantity,quantidade):null})}}/><span className="guided-hint">Antes: {p.requestedQuantity} un. · Agora: <strong>{e.desiredQuantity} un.</strong>{e.desiredQuantity===0?' (produto retirado da compra)':''}</span></div>
        <div className="guided-field"><div className="guided-field-title"><span>2</span><div><label htmlFor={`distribuidora-${p.quotationItemId}`}>De quem deseja comprar primeiro?</label><small>No automático, começamos pelo menor preço.</small></div></div><select id={`distribuidora-${p.quotationItemId}`} value={automatico?'':e.selectedResponseId??''} disabled={p.offers.length===0||e.desiredQuantity===0} onChange={x=>{if(!x.target.value){alterar(p.quotationItemId,{selectedResponseId:p.offers[0]?.responseId??null,manualSelection:false,championQuantity:null,stockOverrideNote:''});return}const id=Number(x.target.value);const selecionada=p.offers.find(o=>o.responseId===id);alterar(p.quotationItemId,{selectedResponseId:id,manualSelection:true,championQuantity:Math.min(e.desiredQuantity,selecionada?.availableQuantity??e.desiredQuantity),stockOverrideNote:''})}}><option value="">Automático — usar as ofertas mais baratas</option>{p.offers.map(o=><option key={o.responseId} value={o.responseId}>{o.supplierName} — {money(o.unitPrice)} · estoque {o.availableQuantity} un.</option>)}</select>{automatico&&oferta&&<span className="guided-hint">Começaremos por <strong>{oferta.supplierName}</strong>, atualmente em {oferta.position}º lugar no preço.</span>}{p.offers.length===0&&<span className="guided-hint warning">Nenhuma distribuidora ofereceu este produto.</span>}</div>
        <div className={`guided-field ${automatico?'guided-field-disabled':''}`}><div className="guided-field-title"><span>3</span><div><label htmlFor={`quantidade-principal-${p.quotationItemId}`}>Quanto comprar dessa distribuidora?</label><small>O que faltar será buscado nas próximas ofertas.</small></div></div><input id={`quantidade-principal-${p.quotationItemId}`} type="number" min="1" max={e.desiredQuantity} disabled={automatico||!e.selectedResponseId||e.desiredQuantity===0} value={automatico?'':e.championQuantity??''} placeholder={automatico?'Divisão automática':'Informe a quantidade'} onChange={x=>alterar(p.quotationItemId,{championQuantity:x.target.value?Number(x.target.value):null})}/>{!automatico&&oferta&&<div className="quantity-shortcuts"><button type="button" onClick={()=>alterar(p.quotationItemId,{championQuantity:Math.min(e.desiredQuantity,oferta.availableQuantity),stockOverrideNote:''})}>Usar estoque informado ({Math.min(e.desiredQuantity,oferta.availableQuantity)} un.)</button><button type="button" onClick={()=>alterar(p.quotationItemId,{championQuantity:e.desiredQuantity})}>Comprar tudo dela</button></div>}{automatico&&<span className="guided-hint">Não precisa preencher: o sistema fará a divisão usando preço e estoque.</span>}{acimaDoTotal&&<small className="field-error">Essa quantidade não pode ser maior que o total da compra.</small>}{erros[`${prefixo}championQuantity`]&&<small className="field-error">{erros[`${prefixo}championQuantity`]}</small>}</div>
      </div>}
      {excesso&&<div className="plan-note guided-stock-note"><div><strong>Confirmação de estoque necessária</strong><span>A distribuidora informou {oferta.availableQuantity} un., mas você quer comprar {e.championQuantity} un. dela. Explique o que foi combinado com o representante.</span></div><label>Justificativa interna<input autoFocus placeholder="Ex.: representante confirmou mais 5 unidades por telefone" value={e.stockOverrideNote} onChange={x=>alterar(p.quotationItemId,{stockOverrideNote:x.target.value})}/><small>Esta informação não aparecerá no pedido enviado.</small>{!e.stockOverrideNote.trim()&&<small className="field-error">Preencha a justificativa para salvar.</small>}{erros[`${prefixo}stockOverrideNote`]&&<small className="field-error">{erros[`${prefixo}stockOverrideNote`]}</small>}</label></div>}
      <div className={`allocation-preview ${previsao.restante>0?'allocation-preview-warning':''}`}><div className="allocation-preview-title"><strong>Como ficará depois de salvar</strong><span>{previsao.automatico?'Divisão automática':'Divisão escolhida por você'}</span></div>{e.desiredQuantity===0?<p>Este produto será retirado do plano de compra.</p>:previsao.parcelas.length===0?<p>Não há oferta disponível para atender este produto.</p>:<><div className="allocation-preview-lines">{previsao.parcelas.map(parcela=><div key={`${parcela.supplierName}-${parcela.position}`}><span>{parcela.quantity} un.</span><strong>{parcela.supplierName}</strong><small>{parcela.principal?(previsao.automatico?'melhor oferta':'primeira distribuidora'):`complemento · ${parcela.position}ª colocada`}</small></div>)}</div><p>{primeira&&complementos.length===1?<><strong>{primeira.quantity} un.</strong> irão para {primeira.supplierName}. {quantidadeComplementar===1?'A':'As'} <strong>{quantidadeComplementar} {quantidadeComplementar===1?'unidade restante':'unidades restantes'}</strong> {quantidadeComplementar===1?'será completada':'serão completadas'} automaticamente pela {complementos[0].supplierName} ({complementos[0].position}ª colocada).</>:primeira&&complementos.length>1?<><strong>{primeira.quantity} un.</strong> irão para {primeira.supplierName}. As <strong>{quantidadeComplementar} unidades restantes</strong> serão divididas automaticamente entre as próximas ofertas.</>:primeira&&previsao.restante===0?<>As <strong>{e.desiredQuantity} un.</strong> estão cobertas{previsao.parcelas.length===1?` pela ${primeira.supplierName}`:' pelas distribuidoras acima'}.</>:null}{previsao.restante>0&&<> Ainda faltarão <strong>{previsao.restante} un.</strong> por falta de estoque nas propostas.</>}</p></>}</div>
    </article>})}</div>
    <div className="plan-save-note"><strong>Ao salvar:</strong> a composição e os totais serão recalculados. Pedidos já gerados e afetados precisarão ser gerados novamente.</div>
    <div className="modal-actions"><button className="button button-ghost" onClick={aoFechar}>Cancelar</button><button className="button button-primary" disabled={ocupado||erroLocal||!temAlteracoes} title={!temAlteracoes?'Faça alguma alteração no plano para salvar.':undefined} onClick={aoSalvar}>{ocupado?'Salvando...':focado?'Salvar e recalcular compra':'Salvar plano e recalcular'}</button></div>
  </section></div>
}
function ModalTroca({produto,ocupado,aoFechar,aoEscolher,aoAutomatico}:{produto:ComparacaoProduto;ocupado:boolean;aoFechar:()=>void;aoEscolher:(id:number)=>void;aoAutomatico:()=>void}){
  return <div className="modal-backdrop"><section className="modal winner-modal">
    <div className="modal-header modal-header-simple"><div><h2>Trocar campeão</h2><div className="winner-product-title"><PackageCheck/><span>{produto.productName}</span></div></div><button className="icon-button" aria-label="Fechar" onClick={aoFechar}><X/></button></div>
    <div className="winner-options">{produto.offers.map(o=><button key={o.responseId} className="winner-option" disabled={ocupado} onClick={()=>aoEscolher(o.responseId)}><span className="offer-position">{o.position}º</span><div><strong>{o.supplierName}</strong><small>{o.availableQuantity} unidades disponíveis</small></div><strong>{money(o.unitPrice)}</strong></button>)}</div>
    <div className="modal-actions"><button className="button button-ghost" onClick={aoFechar}>Cancelar</button>{produto.manualSelection&&<button className="button button-secondary" onClick={aoAutomatico}><RotateCcw/>Voltar ao automático</button>}</div>
  </section></div>
}
function mensagemErro(e:unknown,padrao:string){return e instanceof ErroApi?e.message:padrao}
